 // ============================================================
// ARTAMON API WORKER v7.0
// Юзеры → ARTAMON_USERS
// Посты/комменты/промо/тикеты/апгрейдер/ивенты → ARTAMON_POSTS
// ============================================================

const CORS = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
        "Access-Control-Max-Age": "86400"
        };

        function json(data, status) {
          return new Response(JSON.stringify(data), {
              status: status || 200,
                  headers: { ...CORS, "Content-Type": "application/json" }
                    });
                    }
                    function err(msg, status) { return json({ ok: false, error: msg }, status || 400); }
                    async function readBody(req) { try { return await req.json(); } catch (e) { return {}; } }

                    // ============================================================
                    // KV HELPERS
                    // ============================================================
                    async function kvGet(env, key, fallback) {
                      try { const v = await env.ARTAMON_POSTS.get(key); if (!v) return fallback; return JSON.parse(v); }
                        catch (e) { return fallback; }
                        }
                        async function kvSet(env, key, value) {
                          try { await env.ARTAMON_POSTS.put(key, JSON.stringify(value)); return true; }
                            catch (e) { return false; }
                            }
                            async function kvGetUser(env, key, fallback) {
                              try { const v = await env.ARTAMON_USERS.get(key); if (!v) return fallback; return JSON.parse(v); }
                                catch (e) { return fallback; }
                                }
                                async function kvSetUser(env, key, value) {
                                  try { await env.ARTAMON_USERS.put(key, JSON.stringify(value)); return true; }
                                    catch (e) { return false; }
                                    }
                                    async function kvDelUser(env, key) { try { await env.ARTAMON_USERS.delete(key); } catch (e) {} }
                                    async function kvListUsers(env) {
                                      try { return await env.ARTAMON_USERS.list({ prefix: "user:" }); }
                                        catch (e) { return { keys: [] }; }
                                        }

                                        // ============================================================
                                        // ADMIN AUTH
                                        // ============================================================
                                        function checkAdmin(env, password) {
                                          const owner = env.ADMIN_PASSWORD || "artamon2024";
                                            const junior = env.JUNIOR_PASSWORD || "junior2024";
                                              if (password === owner) return "owner";
                                                if (password === junior) return "junior";
                                                  return false;
                                                  }
                                                  function requireAdmin(env, password) { return checkAdmin(env, password) ? checkAdmin(env, password) : null; }

                                                  // ============================================================
                                                  // USERS
                                                  // ============================================================
                                                  async function getUser(env, nick) {
                                                    if (!nick) return null;
                                                      const user = await kvGetUser(env, "user:" + nick.toLowerCase(), null);
                                                        if (!user) return null;
                                                          if (!user.inventory) user.inventory = {};
                                                            if (typeof user.coins !== "number") user.coins = 0;
                                                              if (!user.achievements) user.achievements = {};
                                                                if (!user.history) user.history = [];
                                                                  if (!user.owned) user.owned = { avatars: [], backgrounds: [], music: [], themes: [] };
                                                                    if (!Array.isArray(user.owned.avatars)) user.owned.avatars = [];
                                                                      if (!user.wip) user.wip = { active: false, until: 0, startedAt: 0 };
                                                                        if (user.wipUntil && !user.wip.until) user.wip.until = user.wipUntil;
                                                                          if (!user.bonusPercent) user.bonusPercent = 0;
                                                                            return user;
                                                                            }
                                                                            async function saveUser(env, user) {
                                                                              if (!user || !user.nick) return false;
                                                                                user.updatedAt = Date.now();
                                                                                  if (user.wip && user.wip.until) user.wipUntil = user.wip.until;
                                                                                    else user.wipUntil = 0;
                                                                                      if (user.wip && user.wip.until && user.wip.until < Date.now()) {
                                                                                          user.wip.active = false; user.wip.until = 0; user.wipUntil = 0;
                                                                                            }
                                                                                              return await kvSetUser(env, "user:" + user.nick.toLowerCase(), user);
                                                                                              }
                                                                                              function createUser(nick, password) {
                                                                                                return {
                                                                                                    nick, password, coins: 100,
                                                                                                        inventory: {}, achievements: {}, history: [],
                                                                                                            owned: { avatars: [], backgrounds: [], music: [], themes: [] },
                                                                                                                wip: { active: false, until: 0, startedAt: 0 },
                                                                                                                    wipUntil: 0, bonusPercent: 0,
                                                                                                                        banned: false, banReason: "", bannedAt: 0, banUntil: 0,
                                                                                                                            muted: false, mutedUntil: 0,
                                                                                                                                createdAt: Date.now(), updatedAt: Date.now()
                                                                                                                                  };
                                                                                                                                  }
                                                                                                                                  function publicUser(user) {
                                                                                                                                    if (!user) return null;
                                                                                                                                      return {
                                                                                                                                          nick: user.nick, coins: user.coins,
                                                                                                                                              inventory: user.inventory, achievements: user.achievements,
                                                                                                                                                  owned: user.owned || { avatars: [] },
                                                                                                                                                      history: (user.history || []).slice(-50),
                                                                                                                                                          wip: user.wip || { active: false, until: 0 },
                                                                                                                                                              wipUntil: user.wipUntil || 0,
                                                                                                                                                                  bonusPercent: user.bonusPercent || 0,
                                                                                                                                                                      banned: !!user.banned, banReason: user.banReason || "", banUntil: user.banUntil || 0,
                                                                                                                                                                          muted: !!user.muted, mutedUntil: user.mutedUntil || 0,
                                                                                                                                                                              createdAt: user.createdAt
                                                                                                                                                                                };
                                                                                                                                                                                }

