                                                                                                                                                                                                                                                        async function getUpgradeItems(env) {
                                                                                                                                                                                                                                                          const saved = await kvGet(env, "upgrade:items", null);
                                                                                                                                                                                                                                                            if (saved && Array.isArray(saved) && saved.length) return saved;
                                                                                                                                                                                                                                                              return UPGRADE_ITEMS_DEFAULT.slice();
                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                              async function saveUpgradeItems(env, items) { return await kvSet(env, "upgrade:items", items); }
                                                                                                                                                                                                                                                              async function getUpgradeConfig(env) {
                                                                                                                                                                                                                                                                const saved = await kvGet(env, "upgrade:config", null);
                                                                                                                                                                                                                                                                  if (saved && typeof saved === "object") return Object.assign({}, UPGRADE_CONFIG_DEFAULT, saved);
                                                                                                                                                                                                                                                                    return Object.assign({}, UPGRADE_CONFIG_DEFAULT);
                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                    async function saveUpgradeConfig(env, cfg) { return await kvSet(env, "upgrade:config", cfg); }
                                                                                                                                                                                                                                                                    async function findItem(env, id) {
                                                                                                                                                                                                                                                                      const items = await getUpgradeItems(env);
                                                                                                                                                                                                                                                                        for (let i = 0; i < items.length; i++) if (items[i].id === id) return items[i];
                                                                                                                                                                                                                                                                          return null;
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          async function getUpgradeLogs(env) { return await kvGet(env, "upgrade:logs", []); }
                                                                                                                                                                                                                                                                          async function pushUpgradeLog(env, entry) {
                                                                                                                                                                                                                                                                            const logs = await getUpgradeLogs(env);
                                                                                                                                                                                                                                                                              logs.unshift(entry);
                                                                                                                                                                                                                                                                                if (logs.length > 500) logs.length = 500;
                                                                                                                                                                                                                                                                                  await kvSet(env, "upgrade:logs", logs);
                                                                                                                                                                                                                                                                                  }

