                                                                                                                                                                                                                                                                                                                                                      if (path === "/api/admin/user-detail" && method === "POST") return await handleAdminUserDetail(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (path === "/api/admin/bans") return await handleAdminBans(env);
