                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (path === "/api/admin/post-create" && method === "POST") return await handleAdminPostCreate(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (path === "/api/admin/post-delete" && method === "POST") return await handleAdminPostDelete(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (path === "/api/admin/post-toggle" && method === "POST") return await handleAdminPostToggle(request, env);
